 {modal?.type==='admins'?<AdminPanel onClose={()=>setModal(null)}/>:modal&&!['deleteEvent','trash','purgeEvent','deletePerson','purgePerson','revokeAdmin','approveProgram','reopenProgram','personStats'].includes(modal.type)&&<ModalForm key={modal.type+':'+(modal.song?.id||'')+':'+(modal.application?.id||'')+':'+(modal.person||'')} modal={modal} event={e} state={{...state,people:displayPeople}} me={modal.person||me.id} admin={canEdit} busy={busy} ownProfile={!modal.person||modal.person===me.id} onPersonalLink={()=>{setModal(null);openAuth('credentials')}} onClose={()=>setModal(null)} onSubmit={async(action)=>{const next=await act(action);if(next){setModal(null);if(action.type==='newEvent'){setEventId(next.events[next.events.length-1].id);setTab('songs');}if((action.type==='song'&&!action.song)||action.type==='songWithApplication'){setQuery('');setFilter('all');const added=next.events.find(ev=>ev.id===e.id)?.songs.at(-1);setTab('songs');if(added)setDetail(added.id);}notify(action.type==='apply'?(action.members?.some((m:{person:string})=>m.person!==me.id&&m.person!=='__name')?'Музыканты записаны. Основные места и резерв сохранены.':'Заявка добавлена.'):action.type==='songWithApplication'?'Песня и заявка на состав сохранены.':action.type==='song'?'Песня сохранена до модерации. Теперь можно подать заявку на партию.':'Готово. Изменения сохранены.');}return !!next;}}/>}

