 const [custom,setCustom]=useState(''),[applicationComment,setApplicationComment]=useState(''),[extraProfileRole,setExtraProfileRole]=useState('');const [profileRoles,setProfileRoles]=useState<string[]>([...new Set([...ROLES,...(state.people.find(p=>p.id===me)?.roles||[])])]);
