 const titles:Record<string,string>={song:modal.song?'Редактировать песню':modal.group?'Песня для вашего состава':'Предложить песню',apply:editing?'Изменить заявку':modal.group?'Групповая заявка':'Сыграем эту песню',event:'Новая музыкальная встреча',person:'Добавить музыканта',profile:'Мой профиль',settings:'Настройки встречи',help:'Правила записи'};
 const mounted=useRef(true);useEffect(()=>{mounted.current=true;return()=>{mounted.current=false;};},[]);
 const [imageValue,setImageValue]=useState<string|null>(modal.type==='settings'?eventImageUrl(e):null),[imageFile,setImageFile]=useState<File|null>(null),[imagePreview,setImagePreview]=useState<string|null>(modal.type==='settings'?eventImageUrl(e):null),[uploading,setUploading]=useState(false),[formError,setFormError]=useState('');
 useEffect(()=>{if(!imageFile){setImagePreview(imageValue);return;}const url=URL.createObjectURL(imageFile);setImagePreview(url);return()=>URL.revokeObjectURL(url);},[imageFile,imageValue]);
